theorem fourFactors_ne_zero {a b x : ℂ}
    (ha : ‖a‖ = 1) (hb : ‖b‖ = 1) (hx : ‖x‖ < 1) :
    fourFactors a b x ≠ 0

theorem principal_final_denominator_ne_zero {t : ℝ} {d : ℂ}
    (ht₀ : 0 ≤ t) (ht₁ : t < 1) (hd : ‖d‖ = 1) :
    (1 + d * (t : ℂ)) * (1 + (t : ℂ) / d) ≠ 0

theorem n₂_unitary_ne_zero {t : ℝ} {a b : ℂ}
    (ht₀ : 0 ≤ t) (ht₁ : t < 1) (ha : ‖a‖ = 1) (hb : ‖b‖ = 1) :
    n₂ (t : ℂ) a b ≠ 0

theorem regionRegular_special_negative {t : ℝ} {U V : ℂ}
    (ht₀ : 0 < t) (ht₁ : t < 1) (hU : ‖U‖ = 1) (hV : ‖V‖ = 1)
    (hV₁ : 1 + V ≠ 0) : RegionRegular (t : ℂ) (-(t : ℂ)) U V

theorem regionRegular_unitary {t : ℝ} {d U V : ℂ}
    (ht₀ : 0 ≤ t) (ht₁ : t < 1) (hd : ‖d‖ = 1)
    (hU : ‖U‖ = 1) (hV : ‖V‖ = 1) : RegionRegular (t : ℂ) d U V

@[simp] theorem i0NegativeRowEquiv_val (tail : Bool) (n : ℕ × ℕ × ℕ) :
    (i0NegativeRowEquiv tail n).val = (-(n.1 : ℤ) - 1, (n.2.1 : ℤ),
      if tail then -(n.2.2 : ℤ) - 1 else (n.2.2 : ℤ))

@[simp] theorem i0PositiveRowEquiv_val (tail : Bool) (n : ℕ × ℕ × ℕ) :
    (i0PositiveRowEquiv tail n).val = ((n.1 : ℤ), (n.2.1 : ℤ) - 2 * n.1,
      if tail then -(n.1 : ℤ) - n.2.2 - 1 else (n.2.2 : ℤ) - n.1)
